function groupKey(row,group){const d=row.data||{},issued=d.date||'';if(['date','month','year'].includes(group))return issued.slice(0,{date:10,month:7,year:4}[group])||'No invoice date';return String(({vendor:d.vendor,invoice_no:d.invoice_no,po:row.po,status:status(row),folder:row.folder_name})[group]||'Not available');}
