 return filterRows(rows,{folder:overviewFolder,outcome:includeStatus?overviewOutcome:'',query:overviewSearch}).filter(r=>{const d=r.data||{},f=dashboardFilters;return (!start||(d.date&&d.date>=start))&&(!end||(d.date&&d.date<=end))&&(!f.vendor||vendorKey(r)===f.vendor)&&(!f.po||[r.po,d.po_ref].join(' ').toLowerCase().includes(f.po.toLowerCase()))&&((f.min===''&&f.max==='')||(d.currency===f.currency&&d.total!==null&&d.total!==undefined&&d.total!==''&&Number.isFinite(Number(d.total))&&(f.min===''||Number(d.total)>=Number(f.min))&&(f.max===''||Number(d.total)<=Number(f.max))));});
