function vendorKey(r){const raw=r.data?.vendor||'',gst=r.data?.gstin;const vendors=snapshot?.session.master.vendors||[];const norm=x=>String(x||'').normalize('NFKC').toLowerCase().replace(/[^a-z0-9]/g,'');const matches=vendors.filter(v=>(gst&&norm(v.gstin)===norm(gst))||[v.name,...(v.aliases||[])].some(n=>raw&&norm(n)===norm(raw)));return r.result?.vendor_id||r.vendor_id||(matches.length===1?matches[0].id:raw||'Unmatched vendor');}
