 `<div class="upload-layout"><section class="card"><div class="card-header"><h2>Upload a batch</h2><span class="tag">Up to ${who.demo?15:250} files at once</span></div>${!snapshot.session.master.vendors.length?'<div class="notice warning">Your procurement master is empty. Add your <a href="#master">vendors and purchase orders</a> so matching can run. You can still upload and review extracted fields.</div>':''}<div class="dropzone" id="dropzone"><h3>Drop files here</h3><p>PDF, PNG, JPG, WebP, TIFF or BMP<br>Up to 10 MB and 30 pages per invoice.</p><div class="drop-actions"><button class="primary" id="choose-files" ${uploading?'disabled':''}>Choose files</button><button class="secondary" id="choose-folder" ${uploading?'disabled':''}>Choose folder</button></div><input type="file" id="file-input" accept=".pdf,.png,.jpg,.jpeg,.webp,.tif,.tiff,.bmp" multiple hidden><input type="file" id="folder-input" webkitdirectory multiple hidden></div><div id="file-summary"></div><label class="inline-check"><input type="checkbox" id="local-only" ${uploading?'disabled':''}><span>Use independent OCR and rules for this batch.<small style="display:block">Useful for testing the fallback without a Gemini key.</small></span></label><div class="upload-footer"><small>One file = one invoice. Multi-page files stay together.</small><button class="primary" id="start-upload" ${!files.length||uploading?'disabled':''}>${uploading?'Uploading…':'Run invoice checks'} </button></div><div id="upload-progress"></div>${who.demo?`<section class="demo-starter"><div><h3>Try an example invoice</h3><p>Load a fictional PDF into the file list, then choose Run invoice checks.</p></div><button class="secondary" id="demo-example" ${uploading||demoExampleBusy?'disabled':''}>${demoExampleBusy?'Loading PDF...':'Use example PDF'}</button></section><p id="example-error" class="error" role="alert"></p>`:''}</section></div>`;
 $('#choose-files').onclick=()=>$('#file-input').click();$('#choose-folder').onclick=()=>$('#folder-input').click();
