let reviewContext=null,reviewNavigationBusy=false,queueScroll=0,overviewScroll=0,reviewResizeObserver=null;
const reviewTabs=['issues','details','activity'];
const unresolved=c=>['review','block','not_evaluated'].includes(c.level);
function findingCategory(check){
 const code=check.code||'';
 if(check.level==='pass')return 'passed';
 if(check.level==='not_evaluated')return 'waiting';
 if(code.startsWith('receipt'))return 'receipts';
 if(code.startsWith('bank')||code.startsWith('uncertain_bank'))return 'bank';
 if(code.startsWith('missing')||code.startsWith('uncertain'))return 'missing';
 if(/^(vendor|gstin|po|mapping|duplicate|possible_duplicate)/.test(code))return 'identity';
 return 'amounts';
}
function groupedFindings(checks){
 const groups=[['missing','Missing or uncertain information','Check the original before assuming the document omitted a value.','Edit missing details','invoice-info'],['identity','Vendor and purchase order','Resolve identity, PO mapping and duplicate findings.','Vendor and PO details','vendor-po'],['amounts','Amounts, tax and line items','Compare extracted values with the original and agreed terms.','Review line items','line-items'],['receipts','Goods received','Accepted receipt evidence is independent of the invoice.','Record or correct receipt','receipts'],['bank','Bank details','Correct extraction separately from independent verification.','Review bank details','bank-review'],['waiting','Checks waiting on information','These checks cannot run until the stated prerequisite is available.','Edit prerequisites','invoice-info'],['passed','Passed checks','These checks passed; approval remains a separate action.',null,null]];
 return groups.map(([key,title,description,action,target])=>({key,title,description,action,target,checks:checks.filter(c=>findingCategory(c)===key)})).filter(g=>g.checks.length).sort((a,b)=>Number(b.checks.some(c=>c.level==='block'))-Number(a.checks.some(c=>c.level==='block'))||Number(b.checks.some(unresolved))-Number(a.checks.some(unresolved)));
}
function reviewSummary(row){const checks=row.result?.checks||[],n=checks.filter(unresolved).length;if(row.accepted)return 'Approved and read-only. No payment was initiated.';if(['queued','running'].includes(row.execution))return 'Processing is in progress. Review the saved result when it becomes available.';if(row.execution==='failed')return 'Processing was interrupted. Retry or inspect the original document.';if(!checks.length)return 'Checks will appear when extraction completes.';if(!n)return 'Required checks passed. Compare the source before human approval.';const blocked=checks.filter(c=>c.level==='block').length;return blocked?`${blocked} blocking finding${blocked===1?'':'s'} and ${n-blocked} other unresolved check${n-blocked===1?'':'s'}. Resolve these before approval.`:`${n} unresolved check${n===1?'':'s'}. Confirm extracted information and resolve the findings before approval.`;}
function displayFinding(check){const missing=check.code.startsWith('missing_'),uncertain=check.code.startsWith('uncertain_');const outcome=({pass:'Passed',review:'Needs review',block:'Blocked',not_evaluated:'Waiting on information',info:'Information'})[check.level]||check.level;const next=missing?'Value not extracted: check the original and enter the value if shown. Request clarification only if the original actually omits required information.':uncertain?'Ambiguous reading: compare this value with the original. Correct it or confirm the source using the appropriate review action.':check.fix;
 return `<li class="compact-finding outcome-${esc(check.level)}"><div><strong>${esc(check.message)}</strong><span class="finding-outcome">${esc(outcome)}</span></div><p>${esc(next||'Resolve the stated prerequisite and rerun checks.')}</p>${check.evidence?.line?`<p class="micro">Source invoice line ${esc(check.evidence.line)}</p>`:''}${Object.keys(check.evidence||{}).length?`<details><summary>Expected / observed and source evidence</summary><pre>${esc(pretty(check.evidence))}</pre></details>`:''}</li>`;
}
function issueGroupsHTML(row){return groupedFindings(row.result?.checks||[]).map(g=>{const count=g.checks.filter(unresolved).length,blocked=g.checks.some(c=>c.level==='block'),focusField=g.key==='missing'?g.checks.map(c=>c.evidence?.field||c.code.replace(/^(missing_|uncertain_)/,'')).find(k=>fields.some(([f])=>f===k)):g.key==='identity'&&g.checks.some(c=>c.code.startsWith('po'))?'review-po':'';return `<details class="issue-group ${blocked?'has-block':''}" data-issue-group="${g.key}" ${count&&g.key!=='waiting'?'open':''}><summary><span>${g.title}</span><span class="micro">${count?count+' unresolved':g.checks.length+' '+(g.key==='passed'?'passed':'informational')}${blocked?' ? Blocked':''}</span></summary><p>${g.description}</p>${g.action?`<button class="secondary small" data-issue-action="${g.target}" data-focus-field="${esc(focusField||'')}">${g.action}</button>`:''}<ul>${g.checks.slice(0,3).map(displayFinding).join('')}</ul>${g.checks.length>3?`<details class="more-findings"><summary>Show ${g.checks.length-3} more findings</summary><ul>${g.checks.slice(3).map(displayFinding).join('')}</ul></details>`:''}</details>`;}).join('')||'<p class="muted">No checks available yet.</p>';}
function editorField(key,label,data,locked){const value=data[key],ev=data.evidence?.[key],uncertain=data.uncertain_fields?.includes(key),missing=value===null||value===undefined||value==='';return `<div class="review-field"><label for="field-${key}">${label}${missing?'<small>Not extracted</small>':uncertain?'<small>Confirm source</small>':''}</label>${key==='tax_basis'?`<select id="field-${key}" name="${key}" ${locked?'disabled':''}><option value="">Not established</option><option value="exclusive" ${value==='exclusive'?'selected':''}>Exclusive of tax</option><option value="inclusive" ${value==='inclusive'?'selected':''}>Inclusive of tax</option></select>`:`<input id="field-${key}" name="${key}" value="${esc(value)}" ${['subtotal','tax','total','tax_rate'].includes(key)?'type="number" step="any"':'type="text"'} ${key==='date'?'placeholder="YYYY-MM-DD"':''} ${locked?'disabled':''}>`}${ev?.snippet?`<details class="field-source"><summary>Source</summary><span class="field-evidence">Page ${esc(ev.page||'not recorded')}: ${esc(ev.snippet)}${ev.reviewer_verification?' ? Verified by reviewer':''}</span></details>`:''}</div>`;}
function lineHTML(l,index,locked){return `<tr data-source-line="${index+1}"><td class="line-number">${index+1}</td><td><textarea rows="2" aria-label="Line ${index+1} description" data-line="item" ${locked?'disabled':''}>${esc(l.item)}</textarea></td>${[['qty','Quantity'],['unit','Unit'],['unit_price','Unit price'],['line_total','Line amount']].map(([k,label])=>`<td><input aria-label="Line ${index+1} ${label}" data-line="${k}" value="${esc(l[k])}" ${k!=='unit'?'type="number" step="any"':''} ${locked?'disabled':''}></td>`).join('')}<td>${locked?'':`<button type="button" class="remove-line" aria-label="Remove line ${index+1}">Remove</button>`}</td></tr>`;}
