 async function render(){const request=++sequence;const pan={top:stage.scrollTop||c.sourceView?.scrollTop||0,left:stage.scrollLeft||c.sourceView?.scrollLeft||0};remember();host.querySelector('[data-prev]').disabled=true;host.querySelector('[data-next]').disabled=true;try{const ratio=window.devicePixelRatio||1,w=Math.min(3200,Math.max(64,Math.round(stage.clientWidth*ratio*zoom/100))),h=Math.min(8192,Math.max(64,Math.round((fitPage?stage.clientHeight:8192)*ratio*zoom/100)));const response=await api(`/sessions/${c.folder}/invoices/${c.row.id}/preview-page?page=${pageNumber}&width=${w}&height=${h}`);const blob=await response.blob();if(closed||request!==sequence)return;const count=Number(response.headers.get('X-Page-Count'))||1;host.querySelector('[data-page]').textContent=`Page ${pageNumber} of ${count}`;host.querySelector('[data-page]').hidden=count===1;host.querySelector('[data-prev]').hidden=count===1;host.querySelector('[data-next]').hidden=count===1;host.querySelector('[data-prev]').disabled=pageNumber===1;host.querySelector('[data-next]').disabled=pageNumber>=count;if(!blob.type.startsWith('image/'))throw new Error('Invalid page preview');const next=URL.createObjectURL(blob);canvas.innerHTML=documentHTML(next,'image/png');canvas.style.width=zoom+'%';canvas.style.height=fitPage?zoom+'%':'auto';canvas.style.aspectRatio=response.headers.get('X-Page-Width')+'/'+response.headers.get('X-Page-Height');if(previewURL)URL.revokeObjectURL(previewURL);previewURL=next;const rendered=canvas.querySelector('img');if(rendered)rendered.onload=()=>{stage.scrollTop=pan.top;stage.scrollLeft=pan.left;remember();};host.querySelector('.viewer-error').textContent='';}catch(error){if(!closed&&request===sequence)host.querySelector('.viewer-error').textContent='Preview unavailable. Download or open the original to inspect it.';}}
