 if(state?.draft&&!background){for(const [k,v] of Object.entries(state.draft.fields))$('#review-form').elements[k].value=v;$('#line-rows').innerHTML=state.draft.lines.map((l,i)=>lineHTML(l,i,locked)).join('');$('#review-po').value=state.draft.po;$('#confirm-source').checked=state.draft.confirmed;wireRemoveLines();}
 if(state){$$('[data-issue-group]').forEach(el=>{if(Object.hasOwn(state.groupStates||{},el.dataset.issueGroup))el.open=state.groupStates[el.dataset.issueGroup];});reviewTabs.forEach(k=>$('#review-panel-'+k).scrollTop=state.scroll[k]||0);}
 $('#review-form').dataset.dirty=String(reviewContext.dirty);$('#review-updated').hidden=!reviewContext.stale;updateReviewActions();
 $('#reload-review').onclick=async()=>{if(await confirmReviewLeave()){reviewContext.dirty=false;await renderDetail();}};
