 if($('#prepare-followup'))$('#prepare-followup').onclick=()=>prepareFollowup(row);
 $('#expand-document').onclick=expandDocument;$('#open-original').onclick=()=>{if(objectURL)window.open(objectURL,'_blank','noopener');};
