 try{const response=await api(`/sessions/${folder}/invoices/${row.id}/file`);if(page!=='detail'||selected!==row.id||sid!==folder||epoch!==workspaceEpoch)return;const blob=await response.blob();if(objectURL)URL.revokeObjectURL(objectURL);objectURL=URL.createObjectURL(blob);reviewContext.mime=blob.type;if(closePageViewer)closePageViewer();if($('#source-preview').querySelector)closePageViewer=mountPageViewer($('#source-preview'),reviewContext);$('#expand-document').disabled=false;$('#open-original').disabled=false;}catch(error){if(page==='detail'&&selected===iid)$('#source-preview').innerHTML='<p class="notice">Preview could not load. Download the original to inspect it.</p>';}
