function renderBankReview(row,locked){const checks=(row.result?.checks||[]).filter(c=>c.code.startsWith('bank')),comparison=checks.find(c=>c.evidence?.invoice_account)?.evidence||{};$('#invoice-findings').insertAdjacentHTML('beforebegin',`<section class="card control-section"><div class="card-header"><h2>Bank-match status</h2><span class="tag">${row.bank_verification?'External verification recorded':'Independent check'}</span></div>${checks.map(c=>`<p><strong>${esc(c.message)}</strong></p>`).join('')||'<p>Not provided</p>'}<dl class="bank-comparison"><dt>Invoice account</dt><dd>${esc(comparison.invoice_account||'Not provided')}</dd><dt>Trusted account</dt><dd>${esc(comparison.trusted_account||'Not provided')}</dd><dt>Invoice IFSC / trusted IFSC</dt><dd>${esc(comparison.invoice_ifsc||'Not provided')} / ${esc(comparison.trusted_ifsc||'Not provided')}</dd></dl><details><summary>Bank source evidence (masked)</summary><pre>${esc(pretty(comparison.source||{}))}</pre></details><p class="micro">Verify payment-detail changes through an established vendor contact. Do not rely only on contact details printed on this invoice. Source confirmation alone cannot clear a mismatch.</p><div class="control-actions"><button class="secondary" id="bank-correct" ${locked?'disabled':''}>Correct bank extraction</button><button class="secondary" id="bank-verify" ${locked?'disabled':''}>Record external verification</button></div></section>`);$('#bank-correct').onclick=()=>correctBankDialog(row);$('#bank-verify').onclick=()=>verifyBankDialog(row);}
async function correctBankDialog(row){try{const folder=sid,epoch=workspaceEpoch;const b=await post(`/sessions/${folder}/invoices/${row.id}/bank/reveal`);if(folder!==sid||epoch!==workspaceEpoch)return;const dialog=controlDialog('Correct bank extraction',`<form><p>Compare every field with the original source. This corrects extraction only; it does not verify a business bank-detail change or update the trusted vendor account.</p>${[['bank_beneficiary','Beneficiary name'],['bank_account','Full invoice account number'],['bank_ifsc','Invoice IFSC']].map(([k,label])=>`<label>${label}<input name="${k}" type="text" value="${esc(b[k])}" maxlength="${k==='bank_account'?100:k==='bank_ifsc'?30:150}" autocomplete="off"></label>`).join('')}<label class="inline-check"><input type="checkbox" name="compared" required><span>I checked these fields against the original and resolved masked, multiple or ambiguous readings.</span></label><label>Correction reason / source reference<textarea name="reason" required minlength="5" maxlength="500"></textarea></label><button class="primary" type="submit">Save extraction correction</button><button class="secondary" type="button" data-cancel>Cancel</button></form>`);bindControlForm(dialog,(f,folder)=>post(`/sessions/${folder}/invoices/${row.id}/bank/correct`,{expected_run:b.run,bank_beneficiary:f.elements.bank_beneficiary.value,bank_account:f.elements.bank_account.value,bank_ifsc:f.elements.bank_ifsc.value,compared_with_source:f.elements.compared.checked,reason:f.elements.reason.value}));}catch(error){showError(error);}}
function verifyBankDialog(row){const dialog=controlDialog('Record independent bank verification',`<form><p>This records external verification for this invoice only. It does not update the trusted vendor account or approve invoices. Do not use contact information found only on this invoice.</p><label>How was the change independently verified?<input name="method" required minlength="5" maxlength="150" placeholder="For example: called an established vendor contact"></label><label>Mandatory note / reference<textarea name="reason" required minlength="5" maxlength="500"></textarea></label><button class="primary" type="submit">Record verification</button><button class="secondary" type="button" data-cancel>Cancel</button></form>`);bindControlForm(dialog,(f,folder)=>post(`/sessions/${folder}/invoices/${row.id}/bank/verify`,{expected_run:row.run,method:f.elements.method.value,reason:f.elements.reason.value}));}
function reviewProcurementHTML(){const c=reviewContext,row=c.row,checks=row.result?.checks||[],vendor=snapshot.session.master.vendors.find(v=>v.id===row.vendor_id),vendorOK=!!vendor&&vendor.status==='approved'&&!checks.some(x=>['gstin','vendor_name'].includes(x.code)&&unresolved(x)),po=!!row.po,locked=row.accepted||['queued','running'].includes(row.execution),masterLocked=snapshot.invoices.some(r=>r.accepted);return `<section class="review-procurement" aria-label="Vendor and purchase order"><div><h2>Vendor &amp; purchase order</h2><small id="reference-draft-note">${c.dirty?'Saved matching status; your invoice edits are not saved yet.':'Reference matching does not approve the invoice.'}</small></div><div class="reference-state"><span>Vendor: <strong>${vendorOK?'Matched':vendor||!row.data?.vendor?'Needs verification':'Not in approved list'}</strong></span>${!vendorOK&&!locked?`<button class="secondary small" id="review-add-vendor" ${masterLocked?'disabled':''}>${vendor?'Verify or link vendor':'Add &amp; approve vendor'}</button>`:''}</div><div class="reference-state"><span>Purchase order: <strong>${po?'Matched':!row.vendor_id||checks.some(x=>x.code.includes('ambiguous'))?'Selection required':'Not found'}</strong></span>${!locked?`<button class="secondary small" id="review-select-po" ${!row.vendor_id?'disabled':''}>Select existing PO</button>${!po?`<button class="secondary small" id="review-add-po" ${!row.vendor_id||masterLocked?'disabled':''}>Add authorised PO</button>`:''}`:''}</div>${!row.vendor_id?'<p class="micro">Resolve the saved vendor match before adding or selecting its PO.</p>':''}${!vendorOK&&masterLocked||!po&&masterLocked?'<p class="micro">This folder has approvals; its procurement master is locked. Existing PO selection remains available for a matched vendor.</p>':''}</section>`;}
